package com.hallowedsep;

import lombok.Data;

import java.time.LocalDate;
import java.util.HashMap;
import java.util.Map;

@Data
public class DailyStats
{
	private String date; // YYYY-MM-DD format
	private int runs;
	private int totalXp;
	private int totalFails;
	private long totalTimeMs;
	private Map<Integer, Integer> floorCompletions = new HashMap<>();
	private int chestsLooted;
	private int grandCoffinsLooted;

	public DailyStats()
	{
		this.date = LocalDate.now().toString();
		for (int i = 1; i <= 5; i++)
		{
			floorCompletions.put(i, 0);
		}
	}

	public DailyStats(String date)
	{
		this.date = date;
		for (int i = 1; i <= 5; i++)
		{
			floorCompletions.put(i, 0);
		}
	}

	public void addRun(int xp, long timeMs)
	{
		this.runs++;
		this.totalXp += xp;
		this.totalTimeMs += timeMs;
	}

	public void addRun(int xp, long timeMs, int fails)
	{
		addRun(xp, timeMs);
		this.totalFails += fails;
	}

	public void incrementFloor(int floor)
	{
		floorCompletions.merge(floor, 1, Integer::sum);
	}

	public int getFloorCompletions(int floor)
	{
		return floorCompletions.getOrDefault(floor, 0);
	}

	public double getHoursPlayed()
	{
		return totalTimeMs / 3_600_000.0;
	}

	public double getXpPerHour()
	{
		if (totalTimeMs == 0) return 0;
		return totalXp / (totalTimeMs / 3_600_000.0);
	}

	public double getAverageXpPerRun()
	{
		if (runs == 0) return 0;
		return (double) totalXp / runs;
	}

	public double getAverageFailsPerRun()
	{
		if (runs == 0) return 0;
		return (double) totalFails / runs;
	}
}

package com.hallowedsep;

import com.google.gson.*;

import java.lang.reflect.Type;
import java.time.Duration;

public class DurationTypeAdapter implements JsonSerializer<Duration>, JsonDeserializer<Duration>
{
	@Override
	public JsonElement serialize(Duration src, Type typeOfSrc, JsonSerializationContext context)
	{
		return new JsonPrimitive(src.toMillis());
	}

	@Override
	public Duration deserialize(JsonElement json, Type typeOfT, JsonDeserializationContext context) throws JsonParseException
	{
		return Duration.ofMillis(json.getAsLong());
	}
}

package com.hallowedsep;

import java.util.ArrayList;
import java.util.List;
import java.util.Set;
import java.util.TreeSet;

final class GoalProjection
{
	private GoalProjection()
	{
	}

	static List<Integer> parseMilestoneLevels(String configuredLevels, int currentLevel, int targetLevel)
	{
		Set<Integer> levels = new TreeSet<>();
		if (configuredLevels == null || configuredLevels.trim().isEmpty())
		{
			return new ArrayList<>(levels);
		}

		String[] parts = configuredLevels.split("[,\\s]+");
		for (String part : parts)
		{
			try
			{
				int level = Integer.parseInt(part.trim());
				if (level > currentLevel && level < targetLevel && level >= 1 && level <= 99)
				{
					levels.add(level);
				}
			}
			catch (NumberFormatException ignored)
			{
				// Ignore malformed entries so one typo does not hide valid milestones.
			}
		}
		return new ArrayList<>(levels);
	}

	static int daysRemaining(int runsRemaining, double runsPerDay)
	{
		if (runsRemaining <= 0 || runsPerDay <= 0)
		{
			return 0;
		}
		return (int) Math.ceil(runsRemaining / runsPerDay);
	}
}

package com.hallowedsep;

import net.runelite.client.config.*;

import java.awt.Color;

@ConfigGroup("hallowedsep")
public interface HallowedSepulchreConfig extends Config
{
	@ConfigSection(
		name = "Display",
		description = "Display settings",
		position = 0
	)
	String displaySection = "display";

	@ConfigSection(
		name = "Tracking",
		description = "What to track",
		position = 1
	)
	String trackingSection = "tracking";

	@ConfigSection(
		name = "Goals",
		description = "Goal settings",
		position = 2
	)
	String goalsSection = "goals";

	@ConfigSection(
		name = "XP Estimates",
		description = "XP estimation values",
		position = 3
	)
	String xpSection = "xp";

	@ConfigItem(
		keyName = "hidePluginTabOutsideSepulchre",
		name = "Hide Plugin Tab Outside Sepulchre",
		description = "Hide the plugin tab outside of the Hallowed Sepulchre",
		section = displaySection,
		position = 1
	)
	default boolean hidePluginTabOutsideSepulchre()
	{
		return true;
	}

