		return true;
	}

	@ConfigItem(
		keyName = "showXpGained",
		name = "Show XP Gained",
		description = "Show XP gained during current run",
		section = displaySection,
		position = 5
	)
	default boolean showXpGained()
	{
		return true;
	}

	// Tracking Section
	@ConfigItem(
		keyName = "trackChests",
		name = "Track Chest Looting",
		description = "Track coffin/chest looting per floor",
		section = trackingSection,
		position = 0
	)
	default boolean trackChests()
	{
		return true;
	}

	@ConfigItem(
		keyName = "trackFails",
		name = "Track Fails",
		description = "Track obstacle fails from damage or Hallowed ring saves",
		section = trackingSection,
		position = 1
	)
	default boolean trackFails()
	{
		return true;
	}

	@ConfigItem(
		keyName = "trackBetweenFloorIdle",
		name = "Track Idle Between Floors",
		description = "Pause run timer and XP/hr between floors",
		section = trackingSection,
		position = 2
	)
	default boolean trackBetweenFloorIdle()
	{
		return true;
	}

	// Goals Section
	@ConfigItem(
		keyName = "targetLevel",
		name = "Target Level",
		description = "Your target Agility level (for projection calculations)",
		section = goalsSection,
		position = 0
	)
	@Range(min = 1, max = 99)
	default int targetLevel()
	{
		return 99;
	}

	@ConfigItem(
		keyName = "runsPerDay",
		name = "Runs Per Day",
		description = "Estimated runs per day (for time projection)",
		section = goalsSection,
		position = 1
	)
	@Range(min = 1, max = 200)
	default int runsPerDay()
	{
		return 25;
	}

	@ConfigItem(
		keyName = "milestoneLevels",
		name = "Milestone Levels",
		description = "Comma-separated milestone levels before the main goal (for example: 92,95,97)",
		section = goalsSection,
		position = 2
	)
	default String milestoneLevels()
	{
		return "92";
	}

	// XP Estimates Section
	@ConfigItem(
		keyName = "estimatedXpPerRun",
		name = "Estimated XP/Run",
		description = "Estimated XP per run (used before you have data)",
		section = xpSection,
		position = 0
	)
	@Range(min = 1000, max = 20000)
