	}
}

package com.hallowedsep;

import lombok.Data;

import java.time.Duration;
import java.time.Instant;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

@Data
public class HallowedSepulchreSession
{
	private Instant sessionStartTime;
	private int totalRuns;
	private int totalXp;
	private int totalFails;
	private long totalTimeMs;

	// Floor completion counts
	private Map<Integer, Integer> floorCompletions = new HashMap<>();

	// Chest loot counts per floor
	private Map<Integer, Integer> chestsLootedPerFloor = new HashMap<>();

	// Grand coffin loot count
	private int grandCoffinLooted;

	// Best times per floor (in milliseconds)
	private Map<Integer, Long> bestFloorTimes = new HashMap<>();

	// Best full run time (in milliseconds)
	private long bestRunTimeMs;

	// Recent runs for averaging (limited to last 50)
	private List<RunSummary> recentRuns = new ArrayList<>();

	// XP at session start for calculating session XP
	private int sessionStartXp;

	public HallowedSepulchreSession()
	{
		this.sessionStartTime = Instant.now();
		for (int i = 1; i <= 5; i++)
		{
			floorCompletions.put(i, 0);
			chestsLootedPerFloor.put(i, 0);
			bestFloorTimes.put(i, Long.MAX_VALUE);
		}
	}

	public void addRun(SepulchreRun run)
	{
		totalRuns++;
		totalXp += run.getTotalXp();
		totalFails += run.getFails();
		totalTimeMs += run.getDuration().toMillis();

		// Update best run time if this was a full run
		if (run.isCompleted() && run.getDuration().toMillis() < bestRunTimeMs || bestRunTimeMs == 0)
		{
			bestRunTimeMs = run.getDuration().toMillis();
		}

		// Update best floor times
		for (Map.Entry<Integer, SepulchreRun.FloorData> entry : run.getFloorData().entrySet())
		{
			int floor = entry.getKey();
			SepulchreRun.FloorData floorData = entry.getValue();

			if (floorData.isCompleted() && floorData.getDuration() != null)
			{
				long floorTime = floorData.getDuration().toMillis();
				Long currentBest = bestFloorTimes.get(floor);

				if (currentBest == null || floorTime < currentBest)
				{
					bestFloorTimes.put(floor, floorTime);
				}
			}
		}

		// Add to recent runs (keep last 50)
		RunSummary summary = new RunSummary();
		summary.setXp(run.getTotalXp());
		summary.setFails(run.getFails());
		summary.setDurationMs(run.getDuration().toMillis());
		summary.setHighestFloor(run.getHighestFloor());
		summary.setCompleted(run.isCompleted());
		summary.setTimestamp(Instant.now().toEpochMilli());

		recentRuns.add(summary);
		if (recentRuns.size() > 50)
		{
			recentRuns.remove(0);
		}
	}

	public void addXp(int xp)
	{
		// This is called per XP drop, but we track via addRun for totals
	}

	public void incrementFloorCompletion(int floor)
	{
		floorCompletions.merge(floor, 1, Integer::sum);
	}

	public void incrementChestsLooted(int floor)
	{
		chestsLootedPerFloor.merge(floor, 1, Integer::sum);
	}

	public void incrementGrandCoffinLooted()
	{
		grandCoffinLooted++;
	}

	public int getFloorCompletions(int floor)
	{
		return floorCompletions.getOrDefault(floor, 0);
	}

	public int getChestsLooted(int floor)
	{
		return chestsLootedPerFloor.getOrDefault(floor, 0);
	}

	public int getTotalChestsLooted()
	{
		return chestsLootedPerFloor.values().stream().mapToInt(Integer::intValue).sum();
	}

	public Duration getBestFloorTime(int floor)
	{
		Long timeMs = bestFloorTimes.get(floor);
		if (timeMs == null || timeMs == Long.MAX_VALUE)
		{
			return null;
		}
		return Duration.ofMillis(timeMs);
	}

	public Duration getBestRunTime()
	{
		if (bestRunTimeMs == 0)
		{
			return null;
		}
		return Duration.ofMillis(bestRunTimeMs);
	}

	public Duration getTotalTime()
	{
		return Duration.ofMillis(totalTimeMs);
	}

	public Duration getSessionDuration()
	{
		return Duration.between(sessionStartTime, Instant.now());
	}

	public double getAverageXpPerRun()
	{
		if (totalRuns == 0)
		{
			return 0;
		}
		return (double) totalXp / totalRuns;
	}

	public double getAverageTimePerRun()
	{
		if (totalRuns == 0)
		{
			return 0;
		}
		return (double) totalTimeMs / totalRuns;
	}

	public double getAverageFailsPerRun()
	{
		if (totalRuns == 0)
		{
			return 0;
		}
		return (double) totalFails / totalRuns;
	}

	public double getXpPerHour()
	{
		if (totalTimeMs == 0)
		{
			return 0;
		}

		double hours = totalTimeMs / 3_600_000.0;
		return totalXp / hours;
	}

	public double getRunsPerHour()
	{
		if (totalTimeMs == 0)
		{
			return 0;
		}

		double hours = totalTimeMs / 3_600_000.0;
		return totalRuns / hours;
	}

	public int getRecentAverageXp(int count)
	{
		if (recentRuns.isEmpty())
		{
			return 0;
		}

		int limit = Math.min(count, recentRuns.size());
		int startIndex = recentRuns.size() - limit;

		int sum = 0;
		for (int i = startIndex; i < recentRuns.size(); i++)
		{
			sum += recentRuns.get(i).getXp();
		}

		return sum / limit;
	}

	public int getRecentAverageXpForHighestFloor(int highestFloor, int count)
	{
		if (recentRuns.isEmpty() || highestFloor <= 0 || count <= 0)
		{
			return 0;
		}

		int sum = 0;
		int matched = 0;
		for (int i = recentRuns.size() - 1; i >= 0 && matched < count; i--)
		{
			RunSummary run = recentRuns.get(i);
			if (run.getHighestFloor() == highestFloor)
			{
				sum += run.getXp();
				matched++;
			}
		}

		if (matched == 0)
		{
			return 0;
		}
		return sum / matched;
	}

	/**
	 * Initialize maps after deserialization
	 */
	public void initializeAfterLoad()
	{
		if (floorCompletions == null)
		{
			floorCompletions = new HashMap<>();
		}
		if (chestsLootedPerFloor == null)
		{
			chestsLootedPerFloor = new HashMap<>();
		}
		if (bestFloorTimes == null)
		{
			bestFloorTimes = new HashMap<>();
		}
		if (recentRuns == null)
		{
			recentRuns = new ArrayList<>();
		}

		// Ensure all floors have entries
		for (int i = 1; i <= 5; i++)
		{
			floorCompletions.putIfAbsent(i, 0);
			chestsLootedPerFloor.putIfAbsent(i, 0);
			bestFloorTimes.putIfAbsent(i, Long.MAX_VALUE);
		}
	}

	@Data
	public static class RunSummary
	{
		private int xp;
		private int fails;
		private long durationMs;
		private int highestFloor;
		private boolean completed;
		private long timestamp;
	}
}

package com.hallowedsep;

import com.google.gson.*;

import java.lang.reflect.Type;
import java.time.Instant;

public class InstantTypeAdapter implements JsonSerializer<Instant>, JsonDeserializer<Instant>
{
	@Override
	public JsonElement serialize(Instant src, Type typeOfSrc, JsonSerializationContext context)
	{
		return new JsonPrimitive(src.toEpochMilli());
	}

	@Override
	public Instant deserialize(JsonElement json, Type typeOfT, JsonDeserializationContext context) throws JsonParseException
	{
		return Instant.ofEpochMilli(json.getAsLong());
	}
}

package com.hallowedsep;

import lombok.Data;

import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import java.util.*;

@Data
public class PersistentStats
{
	// All-time stats
	private int allTimeRuns;
	private int allTimeXp;
	private int allTimeFails;
	private long allTimeMs;
	private Map<Integer, Integer> allTimeFloorCompletions = new HashMap<>();
	private int allTimeChestsLooted;
	private int allTimeGrandCoffins;

	// Best times (in milliseconds)
	private long bestRunTimeMs;
	private Map<Integer, Long> bestFloorTimes = new HashMap<>();
	private Map<Integer, Long> bestRunTimesByFloors = new HashMap<>();

	// Daily stats - keyed by date string (YYYY-MM-DD)
	private Map<String, DailyStats> dailyHistory = new LinkedHashMap<>();

	// Starting XP when we first started tracking
	private int startingXp;
	private String startDate;

	// Current goal phase stats. These are reset when the main goal changes.
	private String phaseStartDate;
	private int phaseStartLevel;
	private int phaseStartXp;
	private int phaseTargetLevel = 99;
	private int phaseHighestFloor;
	private int phaseRuns;
	private int phaseXp;
	private int phaseFails;
	private long phaseMs;

	public PersistentStats()
	{
		for (int i = 1; i <= 5; i++)
		{
			allTimeFloorCompletions.put(i, 0);
			bestFloorTimes.put(i, Long.MAX_VALUE);
			bestRunTimesByFloors.put(i, Long.MAX_VALUE);
		}
		this.startDate = LocalDate.now().toString();
		this.phaseStartDate = this.startDate;
	}

	public DailyStats getToday()
	{
		return getTodayIfPresent();
	}

	public DailyStats getTodayIfPresent()
	{
		if (dailyHistory == null)
		{
			return null;
		}
		String today = LocalDate.now().toString();
		return dailyHistory.get(today);
	}

	private DailyStats getOrCreateToday()
	{
		if (dailyHistory == null)
		{
			dailyHistory = new LinkedHashMap<>();
		}
		String today = LocalDate.now().toString();
		return dailyHistory.computeIfAbsent(today, DailyStats::new);
	}

	public void recordRun(SepulchreRun run)
	{
		if (run == null) return;

		int runHighestFloor = normalizeFloor(run.getHighestFloor());
		if (runHighestFloor > phaseHighestFloor)
		{
			resetGoalPhase(LocalDate.now(), phaseStartLevel, phaseStartXp, phaseTargetLevel);
			phaseHighestFloor = runHighestFloor;
		}

		int xp = run.getTotalXp();
		int fails = run.getFails();
		long timeMs = run.getDuration().toMillis();

		// Update all-time stats
		allTimeRuns++;
		allTimeXp += xp;
		allTimeFails += fails;
		allTimeMs += timeMs;

		// Update current goal phase stats
		phaseRuns++;
		phaseXp += xp;
		phaseFails += fails;
		phaseMs += timeMs;

		// Update best times only when the floor time came from the game's chat message
		for (Map.Entry<Integer, SepulchreRun.FloorData> entry : run.getFloorData().entrySet())
		{
			int floor = entry.getKey();
			SepulchreRun.FloorData floorData = entry.getValue();

			if (floorData.isCompleted() && floorData.isTimeFromGame() && floorData.getDuration() != null)
			{
				long floorTime = floorData.getDuration().toMillis();
				Long currentBest = bestFloorTimes.get(floor);
				if (currentBest == null || floorTime < currentBest)
				{
					bestFloorTimes.put(floor, floorTime);
				}
			}
		}

		// Update best total times using summed official floor splits
		if (run.isCompleted())
		{
			long totalSplitMs = 0;
			int floorsWithSplits = 0;
			for (int floor = 1; floor <= 5; floor++)
			{
				SepulchreRun.FloorData data = run.getFloorData().get(floor);
				if (data != null && data.isTimeFromGame() && data.getDuration() != null && data.getDuration().toMillis() > 0)
				{
					totalSplitMs += data.getDuration().toMillis();
					floorsWithSplits++;
				}
				else
				{
					break;
				}
			}

			if (floorsWithSplits > 0)
			{
				Long currentBest = bestRunTimesByFloors.get(floorsWithSplits);
				if (currentBest == null || currentBest == Long.MAX_VALUE || totalSplitMs < currentBest)
				{
					bestRunTimesByFloors.put(floorsWithSplits, totalSplitMs);
				}

				// Keep legacy full-run PB in sync when we have all five floors
				if (floorsWithSplits == 5 && (bestRunTimeMs == 0 || totalSplitMs < bestRunTimeMs))
				{
					bestRunTimeMs = totalSplitMs;
				}
			}
		}

		// Update chest counts
		allTimeChestsLooted += run.getTotalChestsLooted();
		if (run.isLootedGrandCoffin())
		{
			allTimeGrandCoffins++;
		}

		// Update daily stats
		DailyStats today = getOrCreateToday();
		today.addRun(xp, timeMs, fails);
		today.setChestsLooted(today.getChestsLooted() + run.getTotalChestsLooted());
		if (run.isLootedGrandCoffin())
		{
			today.setGrandCoffinsLooted(today.getGrandCoffinsLooted() + 1);
		}

		// Update floor completions for today
		for (Map.Entry<Integer, SepulchreRun.FloorData> entry : run.getFloorData().entrySet())
		{
			if (entry.getValue().isCompleted())
			{
				today.incrementFloor(entry.getKey());
			}
		}
	}

	public double getAllTimeHours()
	{
		return allTimeMs / 3_600_000.0;
	}

	public double getAllTimeXpPerHour()
	{
		if (allTimeMs == 0) return 0;
		return allTimeXp / (allTimeMs / 3_600_000.0);
	}

	public double getAllTimeAvgXpPerRun()
	{
		if (allTimeRuns == 0) return 0;
		return (double) allTimeXp / allTimeRuns;
	}

	public double getAllTimeAvgFailsPerRun()
	{
		if (allTimeRuns == 0) return 0;
		return (double) allTimeFails / allTimeRuns;
	}

	public int getAllTimeFloorCompletions(int floor)
	{
		return allTimeFloorCompletions.getOrDefault(floor, 0);
	}

	public int getFloorCompletions(int floor)
	{
		return getAllTimeFloorCompletions(floor);
	}

	public long getBestFloorTimeMs(int floor)
	{
		Long time = bestFloorTimes.get(floor);
		return (time == null || time == Long.MAX_VALUE) ? 0 : time;
	}

	public long getBestRunTimeForFloorsMs(int floors)
	{
		Long time = bestRunTimesByFloors.get(floors);
		return (time == null || time == Long.MAX_VALUE) ? 0 : time;
	}

	/**
	 * Set floor completions directly from the game's chat message.
	 * This uses the game's own tracking which is more accurate.
	 */
	public void setFloorCompletionsFromGame(int floor, int totalCompletions)
	{
		if (floor >= 1 && floor <= 5 && totalCompletions >= 0)
		{
			allTimeFloorCompletions.put(floor, totalCompletions);
		}
	}

	/**
	 * Set personal best time directly from the game's chat message.
	 */
	public void setPersonalBestFromGame(int floor, long timeMs)
	{
		if (floor >= 1 && floor <= 5 && timeMs > 0)
		{
			bestFloorTimes.put(floor, timeMs);
		}
	}

	public List<DailyStats> getRecentDays(int count)
	{
		List<DailyStats> days = new ArrayList<>(dailyHistory.values());
		Collections.reverse(days);
		return days.subList(0, Math.min(count, days.size()));
	}

	public int getDaysTracked()
	{
		LocalDate start = getTrackingStartDate();
		LocalDate today = LocalDate.now();
		if (start.isAfter(today))
		{
			return 1;
		}
		return (int) ChronoUnit.DAYS.between(start, today) + 1;
	}

	public double getAverageRunsPerDay()
	{
		if (allTimeRuns == 0) return 0;
		return (double) allTimeRuns / getDaysTracked();
	}

	public double getAverageHoursPerDay()
	{
		if (allTimeMs == 0) return 0;
		return getAllTimeHours() / getDaysTracked();
	}

	public void resetGoalPhase(LocalDate phaseStart, int currentLevel, int currentXp, int targetLevel)
	{
		LocalDate start = phaseStart != null ? phaseStart : LocalDate.now();
		phaseStartDate = start.toString();
		phaseStartLevel = currentLevel;
		phaseStartXp = currentXp;
		phaseTargetLevel = targetLevel;
		phaseHighestFloor = 0;
		phaseRuns = 0;
		phaseXp = 0;
		phaseFails = 0;
		phaseMs = 0;
	}

	public boolean ensureGoalPhase(int currentLevel, int currentXp, int targetLevel)
	{
		if (parseDate(phaseStartDate) == null || phaseTargetLevel != targetLevel)
		{
			resetGoalPhase(LocalDate.now(), currentLevel, currentXp, targetLevel);
			return true;
		}
		return false;
	}

	public int getPhaseDaysTracked()
	{
		LocalDate start = getPhaseTrackingStartDate();
		LocalDate today = LocalDate.now();
		if (start.isAfter(today))
		{
			return 1;
		}
		return (int) ChronoUnit.DAYS.between(start, today) + 1;
	}

	public int getPhaseActiveDays()
	{
		if (dailyHistory == null || dailyHistory.isEmpty())
		{
			return 0;
		}

		LocalDate start = getPhaseTrackingStartDate();
		LocalDate today = LocalDate.now();
		int activeDays = 0;
		for (DailyStats day : dailyHistory.values())
		{
			if (day == null || day.getRuns() <= 0)
			{
				continue;
			}

			LocalDate date = parseDate(day.getDate());
			if (date != null && !date.isBefore(start) && !date.isAfter(today))
			{
				activeDays++;
			}
		}
		return activeDays;
	}

	public int getPhaseMissedDays()
	{
		return Math.max(0, getPhaseDaysTracked() - getPhaseActiveDays());
	}

	public double getPhaseAverageRunsPerDay()
	{
		if (phaseRuns == 0) return 0;
		return (double) phaseRuns / getPhaseDaysTracked();
	}

	public double getPhaseAverageHoursPerDay()
	{
		if (phaseMs == 0) return 0;
		return (phaseMs / 3_600_000.0) / getPhaseDaysTracked();
	}

	public double getPhaseAverageFailsPerRun()
	{
		if (phaseRuns == 0) return 0;
		return (double) phaseFails / phaseRuns;
	}

	public double getPhaseAverageXpPerRun()
	{
		if (phaseRuns == 0) return 0;
		return (double) phaseXp / phaseRuns;
	}

	public int getProjectionFloor()
	{
		if (phaseHighestFloor > 0)
		{
			return phaseHighestFloor;
		}
		return getHighestCompletedFloor();
	}

	/**
	 * Initialize maps after deserialization
	 */
	public void initializeAfterLoad()
	{
		if (allTimeFloorCompletions == null)
		{
			allTimeFloorCompletions = new HashMap<>();
		}
		if (bestFloorTimes == null)
		{
			bestFloorTimes = new HashMap<>();
		}
		if (bestRunTimesByFloors == null)
		{
			bestRunTimesByFloors = new HashMap<>();
		}
		if (dailyHistory == null)
		{
			dailyHistory = new LinkedHashMap<>();
		}

		// Ensure all floors have entries
		for (int i = 1; i <= 5; i++)
		{
			allTimeFloorCompletions.putIfAbsent(i, 0);
			bestFloorTimes.putIfAbsent(i, Long.MAX_VALUE);
			bestRunTimesByFloors.putIfAbsent(i, Long.MAX_VALUE);
		}

		if (parseDate(startDate) == null)
		{
			startDate = getEarliestHistoryDate().orElse(LocalDate.now()).toString();
		}
		if (parseDate(phaseStartDate) == null)
		{
			phaseStartDate = getTrackingStartDate().toString();
			phaseTargetLevel = phaseTargetLevel > 0 ? phaseTargetLevel : 99;
			if (phaseRuns == 0 && allTimeRuns > 0)
			{
				phaseRuns = allTimeRuns;
				phaseXp = allTimeXp;
				phaseFails = allTimeFails;
				phaseMs = allTimeMs;
			}
		}
		if (phaseHighestFloor <= 0)
		{
			phaseHighestFloor = getHighestCompletedFloor();
		}
	}

	private int getHighestCompletedFloor()
	{
		if (allTimeFloorCompletions == null || allTimeFloorCompletions.isEmpty())
		{
			return 0;
		}

		int highestFloor = 0;
		for (Map.Entry<Integer, Integer> entry : allTimeFloorCompletions.entrySet())
		{
			if (entry.getValue() != null && entry.getValue() > 0)
			{
				highestFloor = Math.max(highestFloor, normalizeFloor(entry.getKey()));
			}
		}
		return highestFloor;
	}

	private LocalDate getTrackingStartDate()
	{
		LocalDate parsedStartDate = parseDate(startDate);
		if (parsedStartDate != null)
		{
			return parsedStartDate;
		}
		return getEarliestHistoryDate().orElse(LocalDate.now());
	}

	private Optional<LocalDate> getEarliestHistoryDate()
	{
		if (dailyHistory == null || dailyHistory.isEmpty())
		{
			return Optional.empty();
		}

		LocalDate earliest = null;
		for (String date : dailyHistory.keySet())
		{
			LocalDate parsedDate = parseDate(date);
			if (parsedDate != null && (earliest == null || parsedDate.isBefore(earliest)))
			{
				earliest = parsedDate;
			}
		}
		return Optional.ofNullable(earliest);
	}

	private LocalDate getPhaseTrackingStartDate()
	{
		LocalDate parsedStartDate = parseDate(phaseStartDate);
		if (parsedStartDate != null)
		{
			return parsedStartDate;
		}
		return getTrackingStartDate();
	}

	private static int normalizeFloor(int floor)
	{
		if (floor < 1 || floor > 5)
		{
			return 0;
		}
		return floor;
	}

	private LocalDate parseDate(String date)
	{
		if (date == null || date.isEmpty())
		{
			return null;
		}

		try
		{
			return LocalDate.parse(date);
		}
		catch (Exception e)
		{
			return null;
		}
	}
}

package com.hallowedsep;

import lombok.Data;

import java.time.Duration;
import java.time.Instant;
import java.util.HashMap;
import java.util.Map;

@Data
public class SepulchreRun
{
	private Instant startTime;
	private Instant endTime;
	private Instant pausedAt;
	private long pausedDurationMs;
	private int startXp;
	private int totalXp;
	private int highestFloor;
	private int fails;
	private boolean completed;
	private boolean lootedGrandCoffin;

	private Map<Integer, FloorData> floorData = new HashMap<>();
	private Map<Integer, Integer> chestsLootedPerFloor = new HashMap<>();

	public void startFloor(int floor)
	{
		FloorData data = new FloorData();
		data.setFloorNumber(floor);
		data.setStartTime(Instant.now());
		floorData.put(floor, data);
	}

	public void completeFloor(int floor, Duration duration)
	{
		FloorData data = floorData.get(floor);
		if (data != null)
		{
			data.setEndTime(Instant.now());
			if (!data.isTimeFromGame())
			{
				data.setDuration(duration);
			}
			data.setCompleted(true);
			if (!data.isTimeFromGame())
			{
				data.setTimeFromGame(false);
			}
		}
		else
		{
			data = new FloorData();
			data.setFloorNumber(floor);
			data.setDuration(duration);
			data.setCompleted(true);
			data.setTimeFromGame(false);
			floorData.put(floor, data);
		}
	}

	public void setFloorTimeFromGame(int floor, Duration duration)
	{
		FloorData data = floorData.get(floor);
		if (data == null)
		{
			data = new FloorData();
			data.setFloorNumber(floor);
			floorData.put(floor, data);
		}
		data.setDuration(duration);
		data.setCompleted(true);
		data.setTimeFromGame(true);
	}

	public void addXp(int xp)
	{
		this.totalXp += xp;
	}

	public void incrementChestsLooted(int floor)
	{
		chestsLootedPerFloor.merge(floor, 1, Integer::sum);
	}

	public void incrementFails()
	{
		fails++;
	}

	public int getChestsLooted(int floor)
	{
		return chestsLootedPerFloor.getOrDefault(floor, 0);
	}

	public int getTotalChestsLooted()
	{
		return chestsLootedPerFloor.values().stream().mapToInt(Integer::intValue).sum();
	}

	public Duration getDuration()
	{
		if (startTime == null)
		{
			return Duration.ZERO;
		}

		Instant end = endTime != null ? endTime : Instant.now();
		long totalMs = Duration.between(startTime, end).toMillis();
		long pausedMs = pausedDurationMs;
		if (pausedAt != null)
		{
			pausedMs += Duration.between(pausedAt, end).toMillis();
		}
		long effectiveMs = Math.max(0, totalMs - pausedMs);
		return Duration.ofMillis(effectiveMs);
	}

	public Duration getFloorDuration(int floor)
	{
		FloorData data = floorData.get(floor);
		if (data != null && data.getDuration() != null)
		{
			return data.getDuration();
		}
		return Duration.ZERO;
	}

	public int getFloorsCompleted()
	{
		return (int) floorData.values().stream().filter(FloorData::isCompleted).count();
	}

	public boolean isPaused()
	{
		return pausedAt != null;
	}

	public void pause()
	{
		if (pausedAt == null)
		{
			pausedAt = Instant.now();
		}
	}

	public void resume()
	{
		resumeAt(Instant.now());
	}

	public void resumeAt(Instant time)
	{
		if (pausedAt != null)
		{
			pausedDurationMs += Duration.between(pausedAt, time).toMillis();
			pausedAt = null;
		}
	}

	@Data
	public static class FloorData
	{
		private int floorNumber;
		private Instant startTime;
		private Instant endTime;
		private Duration duration;
		private boolean completed;
		private boolean timeFromGame;
		private int xpGained;
		private int chestsLooted;
		private int deaths;
	}
}

